{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "page",
      "type": "number",
      "description": "Current page number (1-based). Page 1 is the first page.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(page: number) => void",
      "description": "Called when the page changes.",
      "required": true
    },
    {
      "name": "changeAction",
      "type": "(page: number) => void | Promise<void>",
      "description": "Async action on page change. Fires after onChange and uses React transitions for built-in loading state."
    },
    {
      "name": "totalItems",
      "type": "number",
      "description": "Total number of items. Used to calculate page count. Takes precedence over totalPages if both provided."
    },
    {
      "name": "totalPages",
      "type": "number",
      "description": "Total number of pages. Use when you know page count but not item count."
    },
    {
      "name": "hasMore",
      "type": "boolean",
      "description": "Whether more pages exist after the current one. Use for cursor-based pagination where total is unknown."
    },
    {
      "name": "pageSize",
      "type": "number",
      "description": "Number of items per page. Coerced to a positive integer; non-finite values fall back to the default.",
      "default": "10"
    },
    {
      "name": "pageSizeOptions",
      "type": "number[]",
      "description": "Available page size options. Shows a page size selector dropdown when provided."
    },
    {
      "name": "onPageSizeChange",
      "type": "(pageSize: number) => void",
      "description": "Called when the page size changes. Automatically resets to page 1."
    },
    {
      "name": "variant",
      "type": "'pages' | 'count' | 'compact' | 'dots' | 'input' | 'none'",
      "description": "Visual variant controlling what appears between prev/next buttons. 'pages' shows page number buttons with ellipsis, 'count' shows 'X-Y of Z' text, 'compact' shows 'Page X of Y' (add first/last buttons with hasFirstLast), 'dots' shows dot indicators, 'input' shows an editable page-number box with a leading label ('Page [ n ] / N') flanked by first/last buttons by default (the box needs a known total to clamp against, so it is disabled in cursor/hasMore mode), 'none' shows just prev/next buttons.",
      "default": "'pages'"
    },
    {
      "name": "pageLabel",
      "type": "string",
      "description": "The noun rendered before the editable box in the 'input' variant, e.g. 'Page' or 'Row'. Navigation is always page-based (via onChange); this only relabels the box. Defaults to the localized 'Page'."
    },
    {
      "name": "hasFirstLast",
      "type": "boolean",
      "description": "Whether to show first/last («/») double-chevron buttons flanking prev/next. Applies to the 'input' variant (shown unless false) and the 'compact' variant (shown only when true); other variants ignore it. Omitted when the page count is unknown (cursor/hasMore pagination).",
      "default": "true for 'input'; false for 'compact'"
    },
    {
      "name": "step",
      "type": "number",
      "description": "Number of pages the previous/next buttons advance per click. Clamped to the valid page range, so a step that would overshoot lands on the first/last page. When greater than 1, the buttons' accessible names reflect the stride. Non-integer or values < 1 fall back to 1.",
      "default": "1"
    },
    {
      "name": "siblingCount",
      "type": "number",
      "description": "Number of page buttons to show on each side of the current page. Only applies when variant='pages'.",
      "default": "1"
    },
    {
      "name": "size",
      "type": "'sm' | 'md'",
      "description": "Size of the pagination controls.",
      "default": "'md'"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Whether the component is disabled.",
      "default": "false"
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible label for the navigation landmark.",
      "default": "'Pagination'"
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
